DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='social_reserve_publish' AND pronargs=7; def:=replace(def,'IF p.external_post_id IS NOT NULL OR p.posted_at IS NOT NULL OR EXISTS(SELECT 1 FROM social_publish_ledger WHERE post_id=p.id AND platform=_platform) THEN','IF EXISTS(SELECT 1 FROM social_publish_ledger WHERE post_id=p.id AND platform=_platform) OR (p.external_post_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM social_publish_ledger WHERE post_id=p.id)) THEN'); EXECUTE def; END $$;